CREATE TABLE "affiliate_programs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "business_id" uuid NOT NULL REFERENCES "businesses"("id") ON DELETE cascade, "owner_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE restrict, "name" text NOT NULL, "slug" text NOT NULL UNIQUE, "description" text NOT NULL DEFAULT '', "application_mode" text NOT NULL DEFAULT 'review', "attribution_model" text NOT NULL DEFAULT 'last_click', "attribution_window_days" integer NOT NULL DEFAULT 30, "cookie_consent_required" boolean NOT NULL DEFAULT true, "product_ids" json NOT NULL DEFAULT '[]'::json, "commission_rule" json NOT NULL, "hold_days" integer NOT NULL DEFAULT 30, "minimum_payout_cents" integer NOT NULL DEFAULT 5000, "currency" text NOT NULL DEFAULT 'usd', "status" text NOT NULL DEFAULT 'draft', "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "affiliate_programs_business_name_unique" UNIQUE ("business_id","name"), CONSTRAINT "affiliate_programs_status_check" CHECK ("status" IN ('draft','active','paused','archived')));
CREATE INDEX "affiliate_programs_business_status_idx" ON "affiliate_programs" ("business_id","status");
CREATE TABLE "affiliate_applications" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "program_id" uuid NOT NULL REFERENCES "affiliate_programs"("id") ON DELETE cascade, "applicant_user_id" integer REFERENCES "users"("id") ON DELETE set null, "display_name" text NOT NULL, "email" text NOT NULL, "partner_type" text NOT NULL DEFAULT 'affiliate', "audience_summary" text NOT NULL DEFAULT '', "promotion_plan" text NOT NULL DEFAULT '', "status" text NOT NULL DEFAULT 'pending', "reviewed_by_user_id" integer REFERENCES "users"("id") ON DELETE set null, "review_note" text NOT NULL DEFAULT '', "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "affiliate_applications_program_email_unique" UNIQUE ("program_id","email"), CONSTRAINT "affiliate_applications_status_check" CHECK ("status" IN ('pending','approved','declined','waitlisted','withdrawn')));
CREATE TABLE "affiliate_partners" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "program_id" uuid NOT NULL REFERENCES "affiliate_programs"("id") ON DELETE cascade, "application_id" uuid REFERENCES "affiliate_applications"("id") ON DELETE set null, "user_id" integer REFERENCES "users"("id") ON DELETE set null, "display_name" text NOT NULL, "email" text NOT NULL, "partner_type" text NOT NULL DEFAULT 'affiliate', "code" text NOT NULL UNIQUE, "status" text NOT NULL DEFAULT 'active', "payout_state" text NOT NULL DEFAULT 'not_connected', "fraud_state" text NOT NULL DEFAULT 'clear', "joined_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "affiliate_partners_program_email_unique" UNIQUE ("program_id","email"), CONSTRAINT "affiliate_partners_status_check" CHECK ("status" IN ('active','paused','suspended','terminated')));
CREATE INDEX "affiliate_partners_program_status_idx" ON "affiliate_partners" ("program_id","status");
CREATE TABLE "affiliate_links" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "partner_id" uuid NOT NULL REFERENCES "affiliate_partners"("id") ON DELETE cascade, "name" text NOT NULL, "destination_url" text NOT NULL, "slug" text NOT NULL UNIQUE, "status" text NOT NULL DEFAULT 'active', "click_count" integer NOT NULL DEFAULT 0, "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "affiliate_clicks" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "program_id" uuid NOT NULL REFERENCES "affiliate_programs"("id") ON DELETE cascade, "partner_id" uuid NOT NULL REFERENCES "affiliate_partners"("id") ON DELETE cascade, "link_id" uuid REFERENCES "affiliate_links"("id") ON DELETE set null, "click_token" text NOT NULL UNIQUE, "anonymous_id" text, "user_id" integer REFERENCES "users"("id") ON DELETE set null, "ip_hash" text NOT NULL, "user_agent_hash" text NOT NULL, "destination_url" text NOT NULL, "consent_state" text NOT NULL DEFAULT 'essential_only', "risk_score" integer NOT NULL DEFAULT 0, "risk_reasons" json NOT NULL DEFAULT '[]'::json, "occurred_at" timestamp NOT NULL DEFAULT now(), "expires_at" timestamp NOT NULL, CONSTRAINT "affiliate_clicks_risk_score_check" CHECK ("risk_score" BETWEEN 0 AND 100));
CREATE INDEX "affiliate_clicks_partner_occurred_idx" ON "affiliate_clicks" ("partner_id","occurred_at");
CREATE INDEX "affiliate_clicks_ip_occurred_idx" ON "affiliate_clicks" ("ip_hash","occurred_at");
CREATE TABLE "affiliate_conversions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "program_id" uuid NOT NULL REFERENCES "affiliate_programs"("id") ON DELETE restrict, "partner_id" uuid NOT NULL REFERENCES "affiliate_partners"("id") ON DELETE restrict, "click_id" uuid REFERENCES "affiliate_clicks"("id") ON DELETE set null, "order_id" uuid REFERENCES "orders"("id") ON DELETE set null, "buyer_user_id" integer REFERENCES "users"("id") ON DELETE set null, "source_reference" text NOT NULL, "cycle_index" integer NOT NULL DEFAULT 0, "gross_revenue_cents" integer NOT NULL, "qualified_revenue_cents" integer NOT NULL, "commission_cents" integer NOT NULL, "currency" text NOT NULL, "status" text NOT NULL DEFAULT 'pending', "risk_score" integer NOT NULL DEFAULT 0, "risk_reasons" json NOT NULL DEFAULT '[]'::json, "hold_until" timestamp NOT NULL, "approved_at" timestamp, "reversed_cents" integer NOT NULL DEFAULT 0, "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "affiliate_conversions_source_unique" UNIQUE ("program_id","source_reference","cycle_index"), CONSTRAINT "affiliate_conversions_status_check" CHECK ("status" IN ('pending','approved','payable','paid','partially_reversed','reversed','disputed','rejected')), CONSTRAINT "affiliate_conversions_amount_check" CHECK ("gross_revenue_cents" >= 0 AND "qualified_revenue_cents" >= 0 AND "commission_cents" >= 0 AND "reversed_cents" >= 0));
CREATE INDEX "affiliate_conversions_partner_status_idx" ON "affiliate_conversions" ("partner_id","status","created_at");
CREATE TABLE "affiliate_ledger_entries" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "program_id" uuid NOT NULL REFERENCES "affiliate_programs"("id") ON DELETE restrict, "partner_id" uuid NOT NULL REFERENCES "affiliate_partners"("id") ON DELETE restrict, "conversion_id" uuid REFERENCES "affiliate_conversions"("id") ON DELETE set null, "kind" text NOT NULL, "amount_cents" integer NOT NULL, "currency" text NOT NULL, "source_reference" text NOT NULL UNIQUE, "status" text NOT NULL DEFAULT 'pending', "available_at" timestamp, "created_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "affiliate_ledger_entries_kind_check" CHECK ("kind" IN ('commission','reversal','adjustment','bonus','payout')), CONSTRAINT "affiliate_ledger_entries_status_check" CHECK ("status" IN ('pending','available','reserved','paid','void')));
CREATE INDEX "affiliate_ledger_partner_status_idx" ON "affiliate_ledger_entries" ("partner_id","status","created_at");
CREATE TABLE "affiliate_payouts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "program_id" uuid NOT NULL REFERENCES "affiliate_programs"("id") ON DELETE restrict, "partner_id" uuid NOT NULL REFERENCES "affiliate_partners"("id") ON DELETE restrict, "amount_cents" integer NOT NULL, "currency" text NOT NULL, "status" text NOT NULL DEFAULT 'provider_pending', "provider_reference" text, "failure_code" text, "ledger_entry_ids" json NOT NULL DEFAULT '[]'::json, "requested_at" timestamp NOT NULL DEFAULT now(), "paid_at" timestamp, "updated_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "affiliate_payouts_status_check" CHECK ("status" IN ('provider_pending','processing','paid','failed','cancelled')));
CREATE TABLE "affiliate_fraud_signals" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "program_id" uuid NOT NULL REFERENCES "affiliate_programs"("id") ON DELETE cascade, "partner_id" uuid REFERENCES "affiliate_partners"("id") ON DELETE set null, "click_id" uuid REFERENCES "affiliate_clicks"("id") ON DELETE set null, "conversion_id" uuid REFERENCES "affiliate_conversions"("id") ON DELETE set null, "signal" text NOT NULL, "severity" text NOT NULL, "evidence" json NOT NULL DEFAULT '{}'::json, "status" text NOT NULL DEFAULT 'open', "reviewed_by_user_id" integer REFERENCES "users"("id") ON DELETE set null, "created_at" timestamp NOT NULL DEFAULT now(), "resolved_at" timestamp, CONSTRAINT "affiliate_fraud_signals_severity_check" CHECK ("severity" IN ('low','medium','high','critical')));
